-- Rule-based home tiles and hero slide schedules.
-- A home_tiles cell is either a fixed image/link or a `source` rule (same shape as a product rail: kind, query,
-- department, sort, atins, limit) that the BFF resolves to the best in-stock product with a real photo. A hero slide may
-- carry optional startsAt/endsAt; outside that window it is not shown. Both changes are additive: existing payloads
-- stay valid.
update slot set payload_schema = '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["theme", "kicker", "title", "sub", "cta", "href", "label"], "properties": {"theme": {"type": "string", "enum": ["ink", "gold", "green", "sand"]}, "kicker": {"type": "string", "minLength": 1, "maxLength": 40}, "title": {"type": "string", "minLength": 1, "maxLength": 60}, "sub": {"type": "string", "minLength": 1, "maxLength": 160}, "cta": {"type": "string", "minLength": 1, "maxLength": 40}, "href": {"type": "string", "minLength": 1, "maxLength": 300, "pattern": "^(/|https://)"}, "label": {"type": "string", "enum": ["AfroTransact", "Sponsored"]}, "imageUrl": {"type": ["string", "null"], "maxLength": 500, "pattern": "^https://"}, "imageAlt": {"type": "string", "minLength": 0, "maxLength": 160}, "startsAt": {"type": ["string", "null"], "maxLength": 40, "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T"}, "endsAt": {"type": ["string", "null"], "maxLength": 40, "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T"}}}'::jsonb where key = 'hero_carousel';

update slot set payload_schema = '{"$schema": "https://json-schema.org/draft/2020-12/schema", "type": "object", "additionalProperties": false, "required": ["title", "cta", "href", "cells"], "properties": {"title": {"type": "string", "minLength": 1, "maxLength": 60}, "cta": {"type": "string", "minLength": 1, "maxLength": 40}, "href": {"type": "string", "minLength": 1, "maxLength": 300, "pattern": "^(/|https://)"}, "cells": {"type": "array", "minItems": 1, "maxItems": 4, "items": {"type": "object", "additionalProperties": false, "anyOf": [{"required": ["label", "href"]}, {"required": ["source"]}], "properties": {"label": {"type": "string", "minLength": 1, "maxLength": 40}, "href": {"type": "string", "minLength": 1, "maxLength": 300, "pattern": "^(/|https://)"}, "imageUrl": {"type": ["string", "null"], "maxLength": 500, "pattern": "^https://"}, "source": {"type": "object", "additionalProperties": false, "required": ["kind"], "properties": {"kind": {"type": "string", "enum": ["search", "department-bestsellers", "fulfilled-fastest", "atins"]}, "query": {"type": "string", "maxLength": 120}, "department": {"type": "string", "maxLength": 60}, "sort": {"type": "string", "enum": ["relevance", "rating", "newest", "price_asc", "price_desc"]}, "atins": {"type": "array", "maxItems": 24, "items": {"type": "string", "maxLength": 20}}, "limit": {"type": "integer", "minimum": 1, "maximum": 24}}}}}}}}'::jsonb where key = 'home_tiles';
